class Solution {
    public boolean canJump(int[] nums) {
        int n = nums.length;
        int[] memo = new int[n]; // 0 unknown, 1 good, 2 bad
        memo[n - 1] = 1;
        return dfs(nums, 0, memo);
    }
    private boolean dfs(int[] nums, int i, int[] memo) {
        if (memo[i] == 1) return true;
        if (memo[i] == 2) return false;
        int furthest = Math.min(i + nums[i], nums.length - 1);
        for (int j = i + 1; j <= furthest; j++) {
            if (dfs(nums, j, memo)) {
                memo[i] = 1;
                return true;
            }
        }
        memo[i] = 2;
        return false;
    }
}

